    'desktop.q.legalForm.ask': 'Legal form',
    'desktop.q.legalForm.why': 'Decides how the company’s capital is booked (the equity accounts) and whether the owner draws a salary or takes money out privately.',
    'desktop.q.legalForm.GmbH': 'GmbH',
    'desktop.q.legalForm.AG': 'AG',
    'desktop.q.legalForm.Einzelfirma': 'Sole proprietorship',
    'desktop.q.legalForm.Einzelfirma.caveat': 'A sole proprietorship pays the owner no salary: withdrawals go to 2850 Privat. Day-to-day books and VAT work; the year-end (AHV on the profit, the tax return) does not.',
    'desktop.q.vatRegistered.ask': 'Registered for VAT (MWST)?',
    'desktop.q.vatRegistered.why': 'Required from CHF 100’000 turnover a year; below that a company can register voluntarily and is then registered. Only a registered company books with VAT codes and files returns.',
    'desktop.q.vatRegistered.yes': 'yes, with a VAT number',
    'desktop.q.vatRegistered.no': 'no',
    'desktop.q.vatRegistered.no.caveat': 'Purchases and sales are booked gross, without VAT codes, and there is no VAT return. The MWST page watches the calendar year’s turnover against the registration threshold.',
    'desktop.q.vatMethod.ask': 'VAT method',
    'desktop.q.vatMethod.why': 'Effective: you pay the VAT you charged minus the VAT on your purchases (input tax). Saldosteuersatz: a flat rate on turnover the tax authority approved, without that deduction.',
    'desktop.q.vatMethod.where': 'Not sure? A company is on the Saldosteuersatz when it applied for it and the tax authority approved a rate; it is filed on form 0553. Your accountant knows. Picked wrong? Change it under Company › VAT as long as this year has no entries.',
    'desktop.q.vatMethod.effective': 'effective method',
    'desktop.q.vatMethod.net-rate': 'Saldosteuersatz (flat rate)',
    'desktop.q.vatMethod.net-rate.caveat': 'Sales are booked gross at the approved flat rate (one or two, as the ESTV allowed), purchases gross without input tax; the return is form 0553, half-yearly. The app asks for the rate next.',
    'desktop.q.basis.ask': 'VAT basis',
    'desktop.q.basis.why': 'When the VAT counts. Vereinnahmt: when the money moves. Vereinbart: when you write your invoice, input tax when a bill arrives.',
    'desktop.q.basis.where': 'Not sure? Vereinbart is what the law provides; vereinnahmt applies when the company asked for it, at registration or later, and the tax authority approved it. Your accountant knows. Picked wrong? Change it under Company › VAT as long as this year has no entries.',
    'desktop.q.noVat': 'We file no VAT returns',
    'desktop.q.noVat.hint': '«We file no VAT returns» is only for a company not in the VAT register (registration is required from CHF 100’000 turnover a year, voluntary below): purchases, sales and invoices are then without VAT. If your accountant fills in the VAT returns, the company is registered. If it is registered and you do not know the answer, ask your accountant. Picked wrong? Change it under Company › VAT as long as this year has no entries.',
    'desktop.q.basis.received': 'vereinnahmt (cash)',
    'desktop.q.basis.agreed': 'vereinbart (invoice)',
    'desktop.q.basis.agreed.caveat': 'An invoice the app issues is booked on its date as a receivable (1100) with its VAT; the payment only settles it. A supplier bill’s input tax counts on the bill’s date once its payment is booked.',
    'desktop.q.period.ask': 'VAT reporting period',
    'desktop.q.period.why': 'How often you file the VAT return. Effective method: quarterly; Saldosteuersatz: half-yearly, unless the ESTV allowed otherwise.',
    'desktop.q.period.quarterly': 'quarterly',
    'desktop.q.period.half-yearly': 'half-yearly',
    'desktop.q.period.monthly': 'monthly',
    'desktop.q.period.monthly.unsupported': 'Monthly returns are not supported yet: the return and its export cover quarters and half years.',
    'desktop.q.fiscalYear.ask': 'Fiscal year',
    'desktop.q.fiscalYear.why': 'The books open on 1 January; opening balances, the year-end and the periods follow the calendar year.',
    'desktop.q.fiscalYear.calendar': 'calendar year (1.1.–31.12.)',
    'desktop.q.fiscalYear.other': 'other',
    'desktop.q.fiscalYear.other.unsupported': 'A fiscal year other than the calendar year is not supported yet: opening balances and the year-end are kept per calendar year.',
    'desktop.q.start.ask': 'Starting point',
    'desktop.q.start.why': 'Both create the same books. When switching, you then enter what the company had on 1 January (bank, open invoices, debts), from last year’s balance sheet.',
    'desktop.q.start.where': 'You enter it later under Company › Opening; until then the bank balance in the app can differ from the bank’s.',
    'desktop.q.start.new': 'new company, empty books',
    'desktop.q.start.switching': 'switching from other bookkeeping',
    'desktop.q.start.switching.caveat': 'Bring the opening balances from your previous program. When you read in the first statement of an account, the app offers its starting balance as the opening balance.',
    'desktop.q.sells.ask': 'What do you sell?',
    'desktop.q.sells.why': 'Decides where purchases and sales are booked by default: material for what you make or build (account 4000) or goods bought to resell (4200); sales of your own products and work with material (3000), of traded goods (3200), of services (3400). Any combination.',
    'desktop.q.sells.made': 'what you make or build yourself, and work you charge with its material (a trade: paint, wood, parts)',
    'desktop.q.sells.traded': 'goods you buy and resell (trade)',
    'desktop.q.sells.services': 'services',
    'desktop.q.foreignCustomers.ask': 'Customers abroad?',
    'desktop.q.foreignCustomers.why': 'A service to a customer abroad is usually not taxed in Switzerland: it is declared, but without VAT.',
    'desktop.q.foreignCustomers.yes': 'yes',
    'desktop.q.foreignCustomers.no': 'no',
    'desktop.q.imports.ask': 'Do you import goods?',
    'desktop.q.imports.why': 'Imports come with customs and import VAT invoices from the courier, booked apart from the goods.',
    'desktop.q.imports.yes': 'yes',
    'desktop.q.imports.no': 'no',
    'desktop.q.employees.ask': 'Employees',
    'desktop.q.employees.why': 'Salaries come from your payroll provider or Treuhand; Vanilla Accounting books the payments, it does not calculate payroll.',
    'desktop.q.employees.none': 'none',
    'desktop.q.employees.owner': 'the owner only',
    'desktop.q.employees.staff': 'staff',
    'desktop.q.employees.owner.caveat': 'Vanilla Accounting books the salary and the AHV, BVG and UVG payments; the payroll itself (Lohnausweis, AHV statement) stays with your provider.',
    'desktop.q.employees.staff.caveat': 'Vanilla Accounting books the salary and the AHV, BVG and UVG payments; the payroll itself (Lohnausweis, AHV statement) stays with your provider.',
    'desktop.q.ownerPaysPrivately.ask': 'Does the owner pay business costs privately?',
    'desktop.q.ownerPaysPrivately.why': 'Then the company owes them back: those receipts are booked on an account that keeps what the company owes the owner (Kontokorrent).',
    'desktop.q.ownerPaysPrivately.yes': 'yes',
    'desktop.q.ownerPaysPrivately.no': 'no',
    'desktop.q.privateUse.ask': 'Private use of a company car or phone',
    'desktop.q.privateUse.why': 'The private share is charged to the owner at the year-end; a firm registered for VAT also pays back the VAT it deducted on that share (own use, Eigenverbrauch). None chosen: no private use.',
    'desktop.q.privateUse.car': 'car',
    'desktop.q.privateUse.phone': 'phone',
    'desktop.q.payouts.ask': 'Do sales reach you as payouts from a webshop or payment provider?',
    'desktop.q.payouts.why': 'A payout bundles sales and fees; it goes over an account of its own that holds what the provider still owes you (clearing account, 1093), so both are booked.',
    'desktop.q.payouts.yes': 'yes',
    'desktop.q.payouts.no': 'no',
